package com.peerpayload.connect.protocol

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.decodeFromJsonElement
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.long
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertThrows
import org.junit.Assert.assertTrue
import org.junit.Test

// The Kotlin protocol against vectors generated by the JavaScript reference
// (connect/android/tools/make-vectors.js): it must read everything the
// desktop app writes, and write what the desktop app reads.
class VectorsTest {
    private val v: JsonObject = json.parseToJsonElement(
        javaClass.classLoader!!.getResource("vectors.json")!!.readText(),
    ).jsonObject

    private val now = v["now"]!!.jsonPrimitive.long

    private fun identity(who: String): Identity {
        val o = v[who]!!.jsonObject
        val s = { k: String -> o[k]!!.jsonPrimitive.content }

        return Identity.fromPem(s("name"), s("certPem"), s("keyPem"), fromB64url(s("boxPrivateRaw")))
    }

    private val alice = identity("alice")
    private val bob = identity("bob")

    private fun card(who: String) = json.decodeFromJsonElement<Card>(v["cards"]!!.jsonObject[who]!!)
    private fun envelope(name: String, inner: Boolean = true): Envelope {
        val e = v["envelopes"]!!.jsonObject[name]!!.jsonObject

        return json.decodeFromJsonElement(if (inner) e["envelope"]!! else e)
    }

    @Test
    fun `identities match the JavaScript ones`() {
        assertEquals(v["alice"]!!.jsonObject["fingerprint"]!!.jsonPrimitive.content, alice.fingerprint)
        assertEquals(v["alice"]!!.jsonObject["boxPublic"]!!.jsonPrimitive.content, alice.boxPublic)
        assertEquals(card("alice"), contactCard(alice))
    }

    @Test
    fun `cards verify, and a card claiming another device ID does not`() {
        assertEquals(bob.fingerprint, verifyCard(card("bob")).fp)
        assertThrows(ProtocolException::class.java) { verifyCard(card("bob").copy(fp = alice.fingerprint)) }
        assertThrows(ProtocolException::class.java) { verifyCard(card("bob").copy(box = "short")) }
        assertThrows(ProtocolException::class.java) { verifyCard(card("bob").copy(name = "")) }
    }

    @Test
    fun `opens envelopes sealed by JavaScript, and rejects tampering`() {
        val opened = open(envelope("aliceToBob"), bob)

        assertEquals(alice.fingerprint, opened.from)
        assertEquals(v["envelopes"]!!.jsonObject["aliceToBob"]!!.jsonObject["payload"], opened.payload)
        assertEquals("pair-accept", open(envelope("bobToAlice"), alice).payload["type"]!!.jsonPrimitive.content)

        assertThrows(ProtocolException::class.java) { open(envelope("tampered", inner = false), bob) }
        assertThrows(ProtocolException::class.java) { open(envelope("aliceToBob"), alice) } // not addressed to her
    }

    @Test
    fun `seals envelopes the other side can open`() {
        val payload = parseMessage(json.parseToJsonElement("""{"type":"decline","transferId":"abcdefgh12"}""").jsonObject)!!.toJson()
        val e = seal(alice, verifyCard(card("bob")), payload, now)

        assertEquals(payload, open(e, bob).payload)
        verifyEnvelopeSignature(e)
        assertThrows(ProtocolException::class.java) { verifyEnvelopeSignature(e.copy(ts = e.ts + 1)) }
    }

    @Test
    fun `pairing links - reads the JavaScript one, round-trips its own`() {
        val p = v["pairing"]!!.jsonObject
        val invite = parseInviteLink(p["link"]!!.jsonPrimitive.content, now)

        assertEquals(alice.fingerprint, invite.card.fp)
        assertEquals(p["secret"]!!.jsonPrimitive.content, invite.secret)
        assertEquals(p["mailbox"]!!.jsonPrimitive.content, invite.mailbox)
        assertEquals(p["expiresAt"]!!.jsonPrimitive.long, invite.expiresAt)
        assertThrows(ProtocolException::class.java) { parseInviteLink(p["link"]!!.jsonPrimitive.content, invite.expiresAt + 1000) }
        assertThrows(ProtocolException::class.java) { parseInviteLink("peerpayload://pair#garbage", now) }

        val own = encodeInviteLink(bob, b64url(ByteArray(16) { it.toByte() }), "https://m.example", now + 60_000)
        assertEquals(bob.fingerprint, parseInviteLink(own, now).card.fp)
    }

    @Test
    fun `inbox tokens and relay tickets are byte-identical to the JavaScript ones`() {
        assertEquals(v["inboxToken"]!!.jsonObject["token"]!!.jsonPrimitive.content, issueInboxToken(alice, ttlSec = 600, now = now))
        assertEquals(
            v["deviceTicket"]!!.jsonObject["ticket"]!!.jsonPrimitive.content,
            issueDeviceTicket(alice, "abcdefgh12", "sender", bob.fingerprint, ttlSec = 600, now = now),
        )
    }

    @Test
    fun `safety code matches`() {
        assertEquals(v["safetyCode"]!!.jsonPrimitive.content, safetyCode(alice.fingerprint, bob.fingerprint))
        assertEquals(safetyCode(alice.fingerprint, bob.fingerprint), safetyCode(bob.fingerprint, alice.fingerprint))
    }

    @Test
    fun `messages - the same valid and invalid sets as JavaScript`() {
        val messages = v["messages"]!!.jsonObject

        for (m in messages["valid"]!!.jsonArray) {
            val parsed = parseMessage(m.jsonObject)

            assertNotNull("rejected: $m", parsed)
            // What we'd send back parses the same.
            assertEquals(parsed, parseMessage(parsed!!.toJson()))
        }

        for (m in messages["invalid"]!!.jsonArray)
            assertNull("accepted: $m", parseMessage(m.jsonObject))

        assertTrue(parseMessage(json.parseToJsonElement("""{"type":"cancel","transferId":"abcdefgh12","future":1}""").jsonObject) is Message.Cancel)
    }

    // The other direction: envelopes sealed here, for tools/check-kotlin.js
    // to open with the JavaScript reference (the desktop app's code).
    @Test
    fun `writes Kotlin-sealed envelopes for the JavaScript check`() {
        val bobCard = verifyCard(card("bob"))
        val messages = listOf(
            Message.PairRequest(b64url(ByteArray(16) { 7 }), verifyCard(contactCard(alice)), "https://mailbox.example"),
            Message.PairAccept,
            Message.Offer("abcdefgh12", listOf(FileSummary("photo.jpg", 1234, 1)), 1, 1234),
            Message.Accept("abcdefgh12", "t0ken", 40123, listOf("192.168.1.7"), true),
            Message.Cancel("abcdefgh12", removed = true),
        )
        val out = kotlinx.serialization.json.buildJsonArray {
            for (m in messages)
                add(json.encodeToJsonElement(Envelope.serializer(), seal(alice, bobCard, m.toJson())))
        }

        java.io.File("build/kotlin-sealed.json").writeText(out.toString())
    }
}
